export type TipoFuente = "oficial" | "empresa" | "prensa" | "consultora" | "academico";
export type Fuente = { id: string; titulo: string; editor: string; fecha: string; url: string; tipo: TipoFuente };
export type Tema = "mercado" | "expansion" | "cliente" | "digital" | "salud" | "talento" | "liderazgo" | "margen" | "regulacion" | "macro" | "demanda";
/** Cifra de adopción digital de la industria, para graficarla: indicador, valor y a qué universo corresponde. `linea` es la línea del diagnóstico de madurez digital (1 clientes, 2 operación, 3 innovación, 4 arquitectura y gobierno). */
export type DatoDigital = { linea: 1 | 2 | 3 | 4; indicador: string; valor: number; unidad: string; alcance: string; anio: string };
/** Iniciativa digital pública de una empresa de la misma industria. */
export type ParDigital = { empresa: string; anio: string; linea: 1 | 2 | 3 | 4 };
export type Hecho = { id: string; temas: Tema[]; hecho: string; fuente: string; nota?: string; dato?: DatoDigital; par?: ParDigital };
export type BaseConocimiento = { id: string; nombre: string; sectorKeys: string[]; paises: string[]; fuentes: Fuente[]; hechos: Hecho[] };

/** Hecho numerado tal como lo recibe el modelo y lo muestra la plataforma. */
export type Evidencia = { n: number; id: string; hecho: string; nota?: string; fuente: Fuente };

